import React from 'react';
import './Dashboard.css'; // Optional: You can style the dashboard similarly to the sign-in form

const Dashboard = () => {
  // Dummy data for upcoming classes
  const upcomingClasses = [
    { time: '9:00 AM', className: 'Yoga for Beginners', location: 'Studio A' },
    { time: '11:00 AM', className: 'HIIT Workout', location: 'Studio B' },
    { time: '1:00 PM', className: 'Strength Training', location: 'Gym Floor' },
  ];

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <h2>Welcome, Coach!</h2>
        <p>Your upcoming classes:</p>
      </header>

      <div className="classes-list">
        <h3>Upcoming Classes</h3>
        <ul>
          {upcomingClasses.map((classItem, index) => (
            <li key={index}>
              <strong>{classItem.className}</strong> at {classItem.time} in {classItem.location}
            </li>
          ))}
        </ul>
      </div>

      <div className="profile-section">
        <h3>Your Profile</h3>
        <p>Email: coach@example.com</p>
        <button className="edit-profile-button">Edit Profile</button>
      </div>
    </div>
  );
};

export default Dashboard;
